import numpy as np
import pandas as pd
import struct
import io

def r_serialize(object, connection=None, ascii=False, xdr=True, version=None, refhook=None):
    """
    Serialize R objects to binary format.
    Returns raw bytes (as a numpy array of uint8).
    """

    # For None connection, return serialized bytes
    if connection is None:
        # Determine serialization type
        if ascii is None or (isinstance(ascii, float) and np.isnan(ascii)):
            type_code = 2  # NA
        elif ascii:
            type_code = 1  # ASCII
        elif not xdr:
            type_code = 3  # native byte order
        else:
            type_code = 0  # XDR (network byte order)

        # Use a simple pickle-based approach with R magic header
        # R uses format: X\n (magic) + version info + serialized data

        # For actual R compatibility, we'd need R's exact serialization format
        # This is a simplified implementation
        serialized = _serialize_object(object, type_code, version, xdr)
        return np.frombuffer(serialized, dtype=np.uint8)
    else:
        # Writing to a connection - not implemented for this exercise
        pass

def _serialize_object(obj, type_code, version, xdr):
    """Serialize a Python object to R's binary format."""

    output = io.BytesIO()

    # R serialization magic header
    output.write(b'X\n')

    # Format version (3 for current R)
    output.write(struct.pack('>I', 3))  # Big-endian 32-bit int

    # R version
    output.write(struct.pack('>I', 0x00040600))  # R 4.6.0

    # Minimum R version
    output.write(struct.pack('>I', 0x00020300))  # R 2.3.0

    # Encoding header
    output.write(b'\x00\x05')  # UTF-8 encoding marker
    output.write(b'UTF-8\x00')

    # Serialize the object itself
    _write_object(output, obj, xdr)

    return output.getvalue()

def _write_object(output, obj, xdr):
    """Write an object in R serialization format."""

    if isinstance(obj, pd.DataFrame):
        _write_dataframe(output, obj, xdr)
    elif isinstance(obj, (list, np.ndarray)):
        if isinstance(obj, np.ndarray):
            _write_numeric_vector(output, obj, xdr)
        else:
            _write_list(output, obj, xdr)
    elif isinstance(obj, (int, float, np.integer, np.floating)):
        _write_numeric_vector(output, np.array([obj]), xdr)
    else:
        _write_numeric_vector(output, np.array([obj]), xdr)

def _write_numeric_vector(output, arr, xdr):
    """Write a numeric vector."""
    output.write(b'\x00\x0e')  # REALSXP type
    length = len(arr) if hasattr(arr, '__len__') else 1
    output.write(struct.pack('>I', length))

    for val in np.atleast_1d(arr):
        if np.isnan(val):
            output.write(struct.pack('>d', np.nan))
        else:
            output.write(struct.pack('>d', float(val)))

def _write_list(output, lst, xdr):
    """Write a list object."""
    output.write(b'\x00\x13')  # VECSXP type
    output.write(struct.pack('>I', len(lst)))

    for item in lst:
        _write_object(output, item, xdr)

def _write_dataframe(output, df, xdr):
    """Write a data frame."""
    output.write(b'\x00\x13')  # VECSXP type
    output.write(struct.pack('>I', len(df.columns)))

    for col in df.columns:
        _write_numeric_vector(output, df[col].values, xdr)
